-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 17: Segurança — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('f112f594-045a-590a-86b4-e93519b9d172', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'No contraste entre segurança e integridade, segurança trata principalmente de:', '["Garantir a validade semântica de todo dado.","Decompor relações sem perdas.","Impedir acesso não autorizado.","Escolher o algoritmo de junção.","Reduzir o número de atributos."]'::jsonb, 2, 'Segurança verifica permissões; integridade verifica condições de validade dos dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.1, páginas 818–821 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('77bbed08-d976-5ce2-b3fa-50166e2c3360', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'O controle de acesso discricionário se caracteriza por permissões concedidas segundo:', '["O algoritmo de ordenação física.","Somente o valor da chave primária.","Apenas a ordem das tuplas.","O instante de criação de um índice.","Decisões de proprietários ou autoridades habilitadas sobre os objetos."]'::jsonb, 4, 'O capítulo usa também a expressão controle discriminatório para essa categoria.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b8f33a1a-e7c9-5f53-9699-aaa459e05a61', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Uma autorização precisa relacionar, entre outros elementos:', '["Apenas o número de conexões.","Usuários, objetos e privilégios permitidos.","Somente processadores e discos.","Somente chaves e índices.","Tabelas e cores de interface."]'::jsonb, 1, 'A permissão deve definir quem pode fazer o quê sobre quais dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4c86bead-9614-5d0d-952e-b7f27ca7c3a5', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Permitir leitura, mas impedir atualização, exemplifica:', '["Privilégios distintos para tipos de operação.","Uma dependência multivalorada.","Ausência de qualquer segurança.","Uma DF entre usuários.","Uma cópia de segurança."]'::jsonb, 0, 'A autorização pode ser específica para consulta, inserção, alteração ou exclusão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d2954897-a812-56df-8214-263dbf0b49f3', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Restringir um empregado à consulta de sua própria linha é um controle:', '["Sem relação com autorização.","De normalização obrigatória.","Exclusivamente sobre criação de índices.","Baseado somente em tamanho físico.","Dependente dos valores envolvidos no acesso."]'::jsonb, 4, 'O critério depende da associação entre o usuário e os valores consultados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('deb0a7da-1a17-5896-8ea8-518e487a17bd', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Qual finalidade tem uma trilha de auditoria?', '["Normalizar o banco.","Eliminar a necessidade de autenticação.","Substituir toda autorização.","Impedir matematicamente qualquer invasão.","Registrar eventos de acesso relevantes para investigação."]'::jsonb, 4, 'Auditoria fornece evidências; não equivale, sozinha, a bloquear operações indevidas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8985f476-c323-5e7d-8a17-c788ea8aa2dc', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'No controle mandatário, decisões de acesso utilizam principalmente:', '["Preferências de cores do usuário.","Quantidade de linhas da tabela.","Classificação dos objetos e nível de liberação dos usuários.","Ordem de inserção.","Tamanho do nome do atributo."]'::jsonb, 2, 'Rótulos e regras obrigatórias restringem o fluxo de informação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.3, páginas 830–834 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('603263e5-c559-5216-b8bc-0fb694f1cb55', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'No modelo de confidencialidade apresentado, a regra de leitura impede:', '["Toda leitura no próprio nível.","Somente leitura de índices.","Uso de tabelas com uma coluna.","Ler informação acima do nível de liberação permitido.","Acesso a qualquer dado público."]'::jsonb, 3, 'A regra impede leitura para cima na hierarquia de classificação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.3, páginas 830–834 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e4d825c5-ed4b-5866-a6c2-152d81413209', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'A regra de escrita voltada a impedir vazamento entre níveis restringe:', '["Qualquer escrita no mesmo nível.","Somente atualizações de números.","Toda leitura de catálogos.","Escrever informação em nível inferior ao permitido pelo modelo.","Somente inserções em tabelas vazias."]'::jsonb, 3, 'Evitar escrita para baixo ajuda a impedir transferência indevida para níveis menos sigilosos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.3, páginas 830–834 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6bcb536d-1831-5029-95f9-97d30582553c', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Um banco estatístico deve fornecer agregados preservando:', '["Apenas a primeira linha de cada grupo.","A confidencialidade das informações individuais.","A ordem de todos os nomes.","A ausência de qualquer soma.","O acesso irrestrito às linhas."]'::jsonb, 1, 'O objetivo combina utilidade estatística e proteção de dados individuais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.4, páginas 835–842 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2bb0e391-2586-5530-ae57-0b2c3050a8d5', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Duas somas sobre grupos quase iguais permitem deduzir o salário de uma pessoa pela diferença. Isso é um risco de:', '["Fragmentação vertical.","Deadlock.","Inferência estatística.","Perda de fechamento.","Dependência parcial."]'::jsonb, 2, 'Resultados agregados combinados podem revelar informação que não foi consultada diretamente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.4, páginas 835–842 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f525ba75-95ce-56f7-8e57-8013f7ab3623', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Proibir consultas que retornem uma única pessoa elimina todo risco de inferência?', '["Não; combinações de consultas podem isolar informações individuais.","Não, porque agregação não é permitida.","Sim, desde que os nomes não sejam exibidos.","Sim, se os totais forem exatos.","Sim, qualquer grupo maior que um é seguro."]'::jsonb, 0, 'O capítulo destaca ataques que combinam resumos aparentemente permitidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.4, páginas 835–842 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('47804b46-21bf-5f7a-8167-62062b2be46a', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Na criptografia simétrica, emissor e receptor utilizam essencialmente:', '["Uma chave primária de tabela.","A senha do DBA em cada linha.","Somente uma chave pública universal.","Uma chave secreta compartilhada para as operações correspondentes.","Um índice agrupado."]'::jsonb, 3, 'A gestão do segredo compartilhado é parte central desse esquema.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.5, páginas 843–848 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a4ac9ae4-3da6-59c1-8ddc-39fd20a86e4b', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Na criptografia de chave pública, qual distinção é fundamental?', '["Uma chave SQL e um índice físico.","Duas chaves que devem ser divulgadas juntas.","Duas cópias públicas da mesma senha.","Uma chave pública e uma chave privada relacionadas, com papéis diferentes.","Uma chave por coluna sem relação matemática."]'::jsonb, 3, 'A chave privada deve permanecer secreta; a pública pode ser divulgada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.5, páginas 843–848 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a1414805-5357-5b33-a711-33d330e57888', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma assinatura digital procura fornecer principalmente evidência de:', '["Confidencialidade obrigatória de todo conteúdo.","Origem e integridade da mensagem assinada.","Compressão sem perdas.","Normalização da mensagem.","Ausência de qualquer chave."]'::jsonb, 1, 'Assinar não significa necessariamente cifrar o conteúdo para ocultá-lo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.5, páginas 843–848 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('396e37ad-2600-5929-9ffc-7af4bc5b72c8', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Cifrar dados resolve automaticamente permissões indevidas concedidas pela aplicação?', '["Sim, ao usar nomes de colunas curtos.","Não; criptografia e controle de acesso são mecanismos complementares.","Sim, toda permissão fica irrelevante.","Sim, se houver uma chave pública.","Não, porque dados cifrados nunca podem ser lidos."]'::jsonb, 1, 'Uma aplicação autorizada a decifrar ainda precisa aplicar as regras de acesso.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.5, páginas 843–848 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7bfc0c7b-82fd-561d-940f-7b75bbb81484', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Fácil', 'Qual comando SQL concede privilégios?', '["GROUP BY.","REVOKE.","CHECK.","ROLLBACK.","GRANT."]'::jsonb, 4, 'GRANT estabelece autorizações sobre objetos conforme o modelo SQL.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.6, páginas 849–854 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('524275fb-a69c-5225-a75e-52f35f2dcbd5', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Fácil', 'Qual comando SQL revoga privilégios?', '["REVOKE.","INSERT.","COMMIT.","SELECT.","CREATE TYPE."]'::jsonb, 0, 'A revogação precisa considerar as regras de dependência e propagação aplicáveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.6, páginas 849–854 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('43cc2e81-eb8c-594b-ad4a-0aad74efe3d9', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'WITH GRANT OPTION permite ao beneficiário, nas condições previstas:', '["Repassar o privilégio recebido.","Confirmar transações de outros usuários.","Ler qualquer tabela sem autorização.","Ignorar todas as restrições de integridade.","Apagar logs de auditoria automaticamente."]'::jsonb, 0, 'A opção trata da delegação do privilégio concedido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.6, páginas 849–854 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7fc6ab79-8dd8-55bb-9ad5-fef6d4ba270d', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Se arquivos físicos puderem ser lidos contornando o SGBD, seus controles internos são suficientes?', '["Não, porque bancos não usam arquivos.","Sim, se o catálogo estiver normalizado.","Não; o sistema operacional e os demais canais também precisam de proteção.","Sim, desde que exista uma visão.","Sim, a autorização SQL cobre qualquer acesso externo."]'::jsonb, 2, 'A segurança precisa considerar o sistema completo, não apenas um ponto de acesso.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.1, páginas 818–821 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
